int main(){try{
 // Event branches are tested separately from smooth-branch finite differences.
 {std::vector<Point>tri{{0,0,0},{1,0,0},{0,1,0}};if(ClosestPrimitive::evaluate(tri,{.2,.2,1},.2).feature!=6||ClosestPrimitive::evaluate(tri,{.5,-.4,.7},.2).feature!=3||ClosestPrimitive::evaluate(tri,{-.4,-.3,.8},.2).feature!=0)throw std::runtime_error("closest feature branch");bool rejected=false;try{ClosestPrimitive::evaluate({{0,0,0},{1,0,0},{2,0,0}},{.2,.2,1},.2);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("collapsed triangle accepted");}
 // Three-node closest point: mechanical tangent includes moving barycentrics.
 {Assembly m(5);std::vector<Point>q(m.size()),v(m.size()),J(m.size());std::vector<unsigned>nodes{m.id(0,3,2),m.id(0,4,2),m.id(0,4,3)};for(auto i:nodes)J[i][2]=1./3;CoupledContactStep base(m,m.masses(),.005,2,.0001,q,v,{{J,0,0,0,nodes}},true,true);SphereStep contact(base,{92,14,-8},8.01,true);auto y=base.mechanics.pack(v);Eigen::VectorXd l(1);l(0)=1e-8;auto g=contact.geometry(y,l);auto e=base.mechanics.evaluate(y);Eigen::VectorXd direction=Eigen::VectorXd::Zero(y.size());for(auto node:nodes)for(unsigned d=0;d<3;++d)direction(base.mechanics.index[3*node+d])=.1*(1+d+node%3);double h=1e-4;auto lo=(y-h*direction).eval(),hi=(y+h*direction).eval();auto gl=contact.geometry(lo,l),gh=contact.geometry(hi,l);Eigen::VectorXd rl=base.mechanics.evaluate(lo).gradient-gl.C*l,rh=base.mechanics.evaluate(hi).gradient-gh.C*l;auto exact=((e.tangent-g.H)*direction).eval();if(((rh-rl)/(2*h)-exact).norm()/exact.norm()>2e-5||((gh.gap-gl.gap)/(2*h)-base.mechanics.h*g.C.transpose()*direction).norm()>2e-8)throw std::runtime_error("moving closest primitive coupled tangent FD");auto result=contact.solve(v);if(result.residual>1e-12||result.gap>1e-10)throw std::runtime_error("moving closest primitive nonlinear solve");}
 for(Point c:std::vector<Point>{{.2,.2,1},{.5,-.4,.7},{-.4,-.3,.8}}){std::vector<Point>tri{{0,0,0},{1,0,0},{0,1,0}};auto g=ClosestPrimitive::evaluate(tri,c,.2);double epsilon=1e-5;for(unsigned a=0;a<9;++a){auto lo=tri,hi=tri;lo[a/3][a%3]-=epsilon;hi[a/3][a%3]+=epsilon;auto gl=ClosestPrimitive::evaluate(lo,c,.2),gh=ClosestPrimitive::evaluate(hi,c,.2);if(std::abs((gh.gap.v-gl.gap.v)/(2*epsilon)-g.gap.g[a])>1e-8)throw std::runtime_error("closest primitive gradient FD");for(unsigned b=0;b<9;++b)if(std::abs((gh.gap.g[b]-gl.gap.g[b])/(2*epsilon)-g.gap.h[N*b+a])>2e-7)throw std::runtime_error("closest primitive Hessian FD");}Eigen::Vector3d moment=Eigen::Vector3d::Zero();for(unsigned a=0;a<3;++a)moment+=Eigen::Vector3d(tri[a][0]-c[0],tri[a][1]-c[1],tri[a][2]-c[2]).cross(Eigen::Vector3d(g.gap.g[3*a],g.gap.g[3*a+1],g.gap.g[3*a+2]));if(moment.norm()>1e-12)throw std::runtime_error("closest primitive sphere torque identity");}
 Eigen::Vector3d point(2,3,4),center(.1,-.3,.4);auto r=SphereStep::radial(point,center,1);auto Q=Eigen::AngleAxisd(.7,Eigen::Vector3d(1,2,3).normalized()).toRotationMatrix();Eigen::Vector3d shift(7,-4,2);auto rotated=SphereStep::radial(Q*point+shift,Q*center+shift,1);if(std::abs(r.gap-rotated.gap)>1e-12||(rotated.normal-Q*r.normal).norm()>1e-12||(rotated.hessian-Q*r.hessian*Q.transpose()).norm()>1e-12)throw std::runtime_error("radial geometry objectivity");
 bool singular=false;try{SphereStep::radial(center,center,1);}catch(const std::runtime_error&){singular=true;}if(!singular)throw std::runtime_error("undefined center normal accepted");
 Assembly m(5);std::vector<Point>q(m.size()),v(m.size()),J(m.size());J[m.id(0,4,2)][2]=1;v[m.id(0,4,2)][2]=-1;CoupledContactStep base(m,m.masses(),.005,2,.0001,q,v,{{J,0,0,0}},true,true);SphereStep sphere(base,{100,12,-8},8);
 auto y=base.mechanics.pack(v);Eigen::VectorXd lambda(1);lambda(0)=1e-8;auto e=base.mechanics.evaluate(y);auto g=sphere.geometry(y,lambda);Eigen::VectorXd direction=Eigen::VectorXd::Zero(y.size());direction(base.mechanics.index[3*m.id(0,4,2)])=.3;direction(base.mechanics.index[3*m.id(0,4,2)+1])=.2;direction(base.mechanics.index[3*m.id(0,4,2)+2])=.1;
 double epsilon=1e-4;Eigen::VectorXd residual[2];Eigen::VectorXd gaps[2];for(unsigned k=0;k<2;++k){Eigen::VectorXd trial=y+(k?1:-1)*epsilon*direction;auto ee=base.mechanics.evaluate(trial);auto gg=sphere.geometry(trial,lambda);residual[k]=ee.gradient-gg.C*lambda;gaps[k]=gg.gap;}auto numerical=((residual[1]-residual[0])/(2*epsilon)).eval();auto analytical=((e.tangent-g.H)*direction).eval();double tangentError=(numerical-analytical).norm()/analytical.norm();if(tangentError>2e-5||((gaps[1]-gaps[0])/(2*epsilon)-base.mechanics.h*g.C.transpose()*direction).norm()>2e-8)throw std::runtime_error("TRUE Lagrangian tangent/gap FD");
 auto result=sphere.solve(std::vector<Point>(m.size()));std::vector<Point>normals;auto impulse=sphere.nodal(result.displacement,result.lambda,normals);auto rest=m.rest();Eigen::Vector3d moment=Eigen::Vector3d::Zero();for(unsigned i=0;i<m.size();++i)moment+=Eigen::Vector3d(rest[i][0]+result.displacement[i][0]-100,rest[i][1]+result.displacement[i][1]-12,rest[i][2]+result.displacement[i][2]+8).cross(Eigen::Vector3d(impulse[i][0],impulse[i][1],impulse[i][2]));if(moment.norm()>1e-15||result.residual>1e-12||result.gap>1e-10||result.lambda.minCoeff()<0)throw std::runtime_error("nonlinear sphere solve/radial moment");std::cout<<"PASS sphere geometry,objectivity,true mechanical tangent FD "<<tangentError<<",radial moment;NOT SOFA certification\n";
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
